const sections: PrayerSection[] = [{"id":"ashrei","heading":"Ashrei","lines":[{"he":"אַשְׁרֵי יושְׁבֵי בֵיתֶךָ. עוד יְהַלְלוּךָ סֶּלָה: אַשְׁרֵי הָעָם שֶׁכָּכָה לּו. אַשְׁרֵי הָעָם שה' אֱלהָיו: תְּהִלָּה לְדָוִד. אֲרומִמְךָ אֱלוהַי הַמֶּלֶךְ. וַאֲבָרְכָה שִׁמְךָ לְעולָם וָעֶד: בְּכָל יום אֲבָרְכֶךָּ. וַאֲהַלְלָה שִׁמְךָ לְעולָם וָעֶד: גָּדול ה' וּמְהֻלָּל מְאד. וְלִגְדֻלָּתו אֵין חֵקֶר: דּור לְדור יְשַׁבַּח מַעֲשיךָ. וּגְבוּרתֶיךָ יַגִּידוּ: הֲדַר כְּבוד הודֶךָ. וְדִבְרֵי נִפְלְאתֶיךָ אָשיחָה: וֶעֱזוּז נורְאתֶיךָ יאמֵרוּ. וּגְדֻלָּתְךָ אֲסַפְּרֶנָּה: זֵכֶר רַב טוּבְךָ יַבִּיעוּ. וְצִדְקָתְךָ יְרַנֵּנוּ: חַנּוּן וְרַחוּם ה'. אֶרֶךְ אַפַּיִם וּגְדָל חָסֶד: טוב ה' לַכּל. וְרַחֲמָיו עַל כָּל מַעֲשיו: יודוּךָ ה' כָּל מַעֲשיךָ. וַחֲסִידֶיךָ יְבָרְכוּכָה: כְּבוד מַלְכוּתְךָ יאמֵרוּ. וּגְבוּרָתְךָ יְדַבֵּרוּ: לְהודִיעַ לִבְנֵי הָאָדָם גְּבוּרתָיו. וּכְבוד הֲדַר מַלְכוּתו: מַלְכוּתְךָ מַלְכוּת כָּל עולָמִים. וּמֶמְשַׁלְתְּךָ בְּכָל דּור וָדר: סומֵךְ ה' לְכָל הַנּפְלִים. וְזוקֵף לְכָל הַכְּפוּפִים: עֵינֵי כל אֵלֶיךָ יְשבֵּרוּ. וְאַתָּה נותֵן לָהֶם אֶת אָכְלָם בְּעִתּו: פּותֵחַ אֶת יָדֶךָ. וּמַשבִּיעַ לְכָל חַי רָצון: צַדִּיק ה' בְּכָל דְּרָכָיו. וְחָסִיד בְּכָל מַעֲשיו: קָרוב ה' לְכָל קרְאָיו. לְכל אֲשֶׁר יִקְרָאֻהוּ בֶאֱמֶת: רְצון יְרֵאָיו יַעֲשה. וְאֶת שַׁוְעָתָם יִשְׁמַע וְיושִׁיעֵם: שׁומֵר ה' אֶת כָּל אהֲבָיו. וְאֵת כָּל הָרְשָׁעִים יַשְׁמִיד: תְּהִלַּת ה' יְדַבֶּר פִּי. וִיבָרֵךְ כָּל בָּשר שֵׁם קָדְשׁו לְעולָם וָעֶד: וַאֲנַחְנוּ נְבָרֵךְ יָהּ מֵעַתָּה וְעַד עולָם. הַלְלוּיָהּ:"}]},{"id":"uva-letzion","heading":"Uva Letzion","lines":[{"he":"וּבָא לְצִיּון גּואֵל וּלְשָׁבֵי פֶשַׁע בְּיַעֲקב. נְאֻם יְהוָה: וַאֲנִי זאת בְּרִיתִי. אותָם אָמַר יְהוָה. רוּחִי אֲשֶׁר עָלֶיךָ וּדְבָרַי אֲשֶׁר שַׂמְתִּי בְּפִיךָ. לא יָמוּשׁוּ מִפִּיךָ וּמִפִּי זַרְעֲךָ וּמִפִּי זֶרַע זַרְעֲךָ. אָמַר יְהוָה. מֵעַתָּה וְעַד עולָם: וְאַתָּה קָדושׁ יושֵׁב תְּהִלּות יִשְׂרָאֵל. וְקָרָא זֶה אֶל זֶה וְאָמַר: קָדושׁ. קָדושׁ. קָדושׁ יְהוָה צְבָאות. מְלא כָל הָאָרֶץ כְּבודו: וּמְקַבְּלִין דֵּין מִן דֵּין. וְאָמְרִין קַדִּישׁ בִּשְׁמֵי מְרומָא עִלָּאָה בֵּית שְׁכִינְתֵּהּ. קַדִּישׁ עַל אַרְעָא עובַד גְּבוּרְתֵּהּ. קַדִּישׁ לְעָלַם וּלְעָלְמֵי עָלְמַיָּא. יְהוָה צְבָאות. מַלְיָא כָל אַרְעָא זִיו יְקָרֵהּ: וַתִּשָּׂאֵנִי רוּחַ. וָאֶשְׁמַע אַחֲרַי קול רַעַשׁ גָדול. בָּרוּךְ כְּבוד יְהוָה מִמְּקומו: וּנְטָלַתְנִי רוּחָא. וּשְׁמָעִית בַּתְרַי קָל זִיעַ סַגִּיא דִּמְשַׁבְּחִין וְאָמְרִין: בְּרִיךְ יְקָרָא דַיהוָה מֵאֲתַר בֵּית שְׁכִינְתֵּהּ: יְהוָה יִמְלךְ לְעולָם וָעֶד: יְהוָה מַלְכוּתֵהּ קָאֵם לְעָלַם וּלְעָלְמֵי עָלְמַיָּא. יְהוָה אֱלהֵי אַבְרָהָם יִצְחָק וְיִשְׂרָאֵל אֲבותֵינוּ. שָׁמְרָה זּאת לְעולָם לְיֵצֶר מַחְשְׁבות לְבַב עַמֶּךָ. וְהָכֵן לְבָבָם אֵלֶיךָ: וְהוּא רַחוּם. יְכַפֵּר עָון וְלא יַשְׁחִית. וְהִרְבָּה לְהָשִׁיב אַפּו. וְלא יָעִיר כָּל חֲמָתו: כִּי אַתָּה אֲדנָי טוב וְסַלָּח. וְרַב חֶסֶד לְכָל קרְאֶיךָ: צִדְקָתְךָ צֶדֶק לְעולָם וְתורָתְךָ אֱמֶת: תִּתֵּן אֱמֶת לְיַעֲקב. חֶסֶד לְאַבְרָהָם. אֲשֶׁר נִשְׁבַּעְתָּ לַאֲבתֵינוּ מִימֵי קֶדֶם: בָּרוּךְ אֲדנָי יום יום יַעֲמָס לָנוּ. הָאֵל יְשׁוּעָתֵנוּ סֶלָה: יְהוָה צְבָאות עִמָּנוּ. מִשְׂגָּב לָנוּ אֱלהֵי יַעֲקב סֶלָה: יְהוָה צְבָאות אַשְׁרֵי אָדָם בּטֵחַ בָּךְ: יְהוָה הושִׁיעָה. הַמֶּלֶךְ יַעֲנֵנוּ בְיום קָרְאֵנוּ: בָּרוּךְ הוּא אֱלהֵינוּ שֶׁבְּרָאָנוּ לִכְבודו. וְהִבְדִּילָנוּ מִן הַתּועִים. וְנָתַן לָנוּ תּורַת אֱמֶת. וְחַיֵּי עולָם נָטַע בְּתוכֵנוּ. הוּא יִפְתַּח לִבֵּנוּ בְּתורָתו. וְיָשֵׂם בְּלִבֵּנוּ אַהֲבָתו וְיִרְאָתו וְלַעֲשׂות רְצונו וּלְעָבְדו בְּלֵבָב שָׁלֵם. לְמַעַן לא נִיגַע לָרִיק וְלא נֵלֵד לַבֶּהָלָה: יְהִי רָצון מִלְּפָנֶיךָ יְהוָה אֱלהֵינוּ וֵאלהֵי אֲבותֵינוּ. שֶׁנִּשְׁמר חֻקֶּיךָ בָּעולָם הַזֶּה. וְנִזְכֶּה וְנִחְיֶה וְנִרְאֶה וְנִירַשׁ טובָה וּבְרָכָה לִשְׁנֵי יְמות הַמָּשִׁיחַ וּלְחַיֵּי הָעולָם הַבָּא. לְמַעַן יְזַמֶּרְךָ כָבוד וְלא יִדּם. יְהוָה אֱלהַי לְעולָם אודֶךָּ: בָּרוּךְ הַגֶּבֶר אֲשֶׁר יִבְטַח בַּיהוָה. וְהָיָה יְהוָה מִבְטַחו: בִּטְחוּ בַיהוָה עֲדֵי עַד. כִּי בְּיָהּ יְהוָה צוּר עולָמִים: וְיִבְטְחוּ בְךָ יודְעֵי שְׁמֶךָ. כִּי לא עָזַבְתָּ דּרְשֶׁיךָ יְהוָה: יְהוָה חָפֵץ לְמַעַן צִדְקו. יַגְדִּיל תּורָה וְיַאְדִּיר:"}]},{"id":"half-kaddish","heading":"Half Kaddish","lines":[{"he":"חזן: יִתְגַּדַּל וְיִתְקַדַּשׁ שְׁמֵהּ רַבָּא. [קהל: אמן] בְּעָלְמָא דִּי בְרָא כִרְעוּתֵהּ וְיַמְלִיךְ מַלְכוּתֵהּ בְּחַיֵּיכון וּבְיומֵיכון וּבְחַיֵּי דְכָל בֵּית יִשרָאֵל בַּעֲגָלָא וּבִזְמַן קָרִיב, וְאִמְרוּ אָמֵן: [קהל: אמן] קהל וחזן: יְהֵא שְׁמֵהּ רַבָּא מְבָרַךְ לְעָלַם וּלְעָלְמֵי עָלְמַיָּא: יִתְבָּרַךְ וְיִשְׁתַּבַּח וְיִתְפָּאַר וְיִתְרומַם וְיִתְנַשּא וְיִתְהַדָּר וְיִתְעַלֶּה וְיִתְהַלָּל שְׁמֵהּ דְּקֻדְשָׁא. בְּרִיךְ הוּא. [קהל: בריך הוא:] לְעֵלָּא בעשי\"ת לְעֵלָּא לְעֵלָּא מִכָּל מִן כָּל בִּרְכָתָא וְשִׁירָתָא תֻּשְׁבְּחָתָא וְנֶחֱמָתָא דַּאֲמִירָן בְּעָלְמָא. וְאִמְרוּ אָמֵן: [קהל: אמן]","note":true}]},{"id":"torah-reading-removing-the-torah-from-ark-va-ani-tefillati","heading":"Va'ani Tefillati","group":"Torah Reading · Removing the Torah from Ark","lines":[{"he":"וַאֲנִי תְפִלָּתִי לְךָ ה' עֵת רָצון אֱלהִים בְּרָב חַסְדֶּךָ עֲנֵנִי בֶּאֱמֶת יִשְׁעֶךָ:"}]},{"id":"torah-reading-removing-the-torah-from-ark-vayehi-binsoa","heading":"Vayehi Binsoa","group":"Torah Reading · Removing the Torah from Ark","lines":[{"he":"וַיְהִי בִּנְסעַ הָאָרן וַיּאמֶר משֶׁה. קוּמָה ה' וְיָפֻצוּ איְבֶיךָ. וְיָנֻסוּ מְשנְאֶיךָ מִפָּנֶיךָ:"},{"he":"כִּי מִצִּיּון תֵּצֵא תורָה. וּדְבַר ה' מִירוּשָׁלָיִם:"},{"he":"בָּרוּךְ שֶׁנָּתַן תּורָה לְעַמּו יִשרָאֵל בִּקְדֻשָּׁתו:"}]},{"id":"torah-reading-removing-the-torah-from-ark-berich-shmei","heading":"Berich Shmei","group":"Torah Reading · Removing the Torah from Ark","lines":[{"he":"בְּרִיךְ שְׁמֵהּ דְּמָרֵא עָלְמָא. בְּרִיךְ כִּתְרָךְ וְאַתְרָךְ. יְהֵא רְעוּתָךְ עִם עַמָּךְ יִשרָאֵל לְעָלַם. וּפוּרְקַן יְמִינָךְ אַחֲזֵי לְעַמָּךְ בְּבֵית מַקְדְּשָׁךְ. וּלְאַמְטויֵי לָנָא מִטּוּב נְהורָךְ וּלְקַבֵּל צְלותָנָא בְּרַחֲמִין. יְהֵא רַעֲוָא קֳדָמָךְ דְּתורִיךְ לָן חַיִּין בְּטִיבוּ. וְלֶהֱוֵי אֲנָא פְקִידָא בְּגו צַדִּיקַיָּא. לְמִרְחַם עָלַי וּלְמִנְטַר יָתִי וְיַת כָּל דִּי לִי וְדִי לְעַמָּךְ יִשרָאֵל. אַנְתְּ הוּא זָן לְכלָּא וּמְפַרְנֵס לְכלָּא. אַנְתְּ הוּא שַׁלִּיט עַל כּלָּא. אַנְתְּ הוּא דְשַׁלִּיט עַל מַלְכַיָּא. וּמַלְכוּתָא דִּילָךְ הִיא. אֲנָא עַבְדָּא דְקוּדְשָׁא בְּרִיךְ הוּא דְּסָגִידְנָא קַמֵּהּ וּמִקַּמֵּי דִּיקַר אורַיְתֵהּ בְּכָל עִדָּן וְעִדָּן. לָא עַל אֱנָשׁ רָחִיצְנָא וְלָא עַל בַּר אֱלָהִין סָמִיכְנָא. אֶלָּא בֶּאֱלָהָא דִשְׁמַיָּא. דְּהוּא אֱלָהָא קְשׁוט וְאורַיְתֵהּ קְשׁוט וּנְבִיאוהִי קְשׁוט. וּמַסְגֵּא לְמֶעְבַּד טַבְוָן וּקְשׁוט. בֵּהּ אֲנָא רָחִיץ. וְלִשְׁמֵהּ יַקִּירָא קַדִּישָׁא אֲנָא אֵמַר תֻּשְׁבְּחָן. יְהֵא רַעֲוָא קֳדָמָךְ דְּתִפְתַּח לִבָּאִי בְּאורַיְתָא. וְתַשְׁלִים מִשְׁאֲלִין דְּלִבָּאי וְלִבָּא דְכָל עַמָּךְ יִשרָאֵל. לְטַב וּלְחַיִּין וְלִשְׁלָם:"}]},{"id":"torah-reading-removing-the-torah-from-ark-gadlu","heading":"Gadlu","group":"Torah Reading · Removing the Torah from Ark","lines":[{"he":"חזן - גַּדְּלוּ לה' אִתִּי וּנְרומְמָה שְׁמו יַחְדָּו:"},{"he":"קהל - לְךָ ה' הַגְּדֻלָּה וְהַגְּבוּרָה וְהַתִּפְאֶרֶת וְהַנֵּצַח וְהַהוד כִּי כל בַּשָּׁמַיִם וּבָאָרֶץ:"}]},{"id":"torah-reading-removing-the-torah-from-ark-lekha-hashem","heading":"Lekha Hashem","group":"Torah Reading · Removing the Torah from Ark","lines":[{"he":"לְךָ ה' הַמַּמְלָכָה וְהַמִּתְנַשּא לְכל לְראשׁ:"},{"he":"רומְמוּ ה' אֱלהֵינוּ וְהִשְׁתַּחֲווּ לַהֲדם רַגְלָיו קָדושׁ הוּא:"},{"he":"רומְמוּ ה' אֱלהֵינוּ וְהִשְׁתַּחֲווּ לְהַר קָדְשׁו כִּי קָדושׁ ה' אֱלהֵינוּ:"}]},{"id":"torah-reading-removing-the-torah-from-ark-av-harachamim","heading":"Av Harachamim","group":"Torah Reading · Removing the Torah from Ark","lines":[{"he":"אָב הָרַחֲמִים הוּא יְרַחֵם עַם עֲמוּסִים וְיִזְכּר בְּרִית אֵיתָנִים. וְיַצִּיל נַפְשׁותֵינוּ מִן הַשָּׁעות הָרָעות. וְיִגְעַר בְּיֵצֶר הָרָע מִן הַנְּשוּאִים. וְיָחן אותָנוּ לִפְלֵיטַת עולָמִים. וִימַלֵּא מִשְׁאֲלותֵינוּ בְּמִדָּה טובָה יְשׁוּעָה וְרַחֲמִים:"}]},{"id":"torah-reading-removing-the-torah-from-ark-vetigaleh-veteraeh","heading":"Vetigaleh Veteraeh","group":"Torah Reading · Removing the Torah from Ark","lines":[{"he":"וְתִגָּלֶה וְתֵרָאֶה מַלְכוּתו עָלֵינוּ בִּזְמַן קָרוב. וְיָחון פְּלֵטָתֵנוּ וּפְלֵטַת עַמּו בֵּית יִשרָאֵל לְחֵן וּלְחֶסֶד וּלְרַחֲמִים וּלְרָצון וְנאמַר אָמֵן. הַכּל הָבוּ גדֶל לֵאלהֵינוּ וּתְנוּ כָבוד לַתּורָה. כּהֵן קְרָב יַעֲמד [פלוני בן פלוני] הַכּהֵן. בָּרוּךְ שֶׁנָּתַן תּורָה לְעַמּו יִשרָאֵל בִּקְדֻשָּׁתו:"},{"he":"קהל: וְאַתֶּם הַדְּבֵקִים בה' אֱלהֵיכֶם חַיִּים כֻּלְּכֶם הַיּום:","note":true}]},{"id":"torah-reading-reading-from-sefer-birkat-hatorah","heading":"Birkat HaTorah","group":"Torah Reading · Reading from Sefer","lines":[{"he":"העולה מברך:"},{"he":"בָּרְכוּ אֶת ה' הַמְברָךְ:"},{"he":"והקהל עונים:"},{"he":"בָּרוּךְ ה' הַמְברָךְ לְעולָם וָעֶד:"},{"he":"והעולה חוזר ואומר:"},{"he":"בָּרוּךְ ה' הַמְברָךְ לְעולָם וָעֶד:"},{"he":"ואח\"כ מברך:"},{"he":"בָּרוּךְ אַתָּה ה' אֱלהֵינוּ מֶלֶךְ הָעולָם אֲשֶׁר בָּחַר בָּנוּ מִכָּל הָעַמִּים וְנָתַן לָנוּ אֶת תּורָתו. בָּרוּךְ אַתָּה ה'"},{"he":"נותֵן הַתּורָה:"},{"he":"אחרי הקריאה מברך העולה:"},{"he":"בָּרוּךְ אַתָּה ה' אֱלהֵינוּ מֶלֶךְ הָעולָם אֲשֶׁר נָתַן לָנוּ תּורַת אֱמֶת וְחַיֵּי עולָם נָטַע בְּתוכֵנוּ. בָּרוּךְ אַתָּה ה' נותֵן הַתּורָה:"}]},{"id":"torah-reading-reading-from-sefer-raising-the-torah","heading":"Raising the Torah","group":"Torah Reading · Reading from Sefer","lines":[{"he":"כשמגביהים הס\"ת אומרים:"},{"he":"וְזאת הַתּורָה אֲשֶׁר שם משֶׁה לִפְנֵי בְּנֵי יִשרָאֵל עַל פִּי ה' בְּיַד משֶׁה:"}]},{"id":"torah-reading-returning-sefer-to-aron-yehalelu","heading":"Yehalelu","group":"Torah Reading · Returning Sefer to Aron","lines":[{"he":"כשמחזירים ספר התורה להיכל אומרים:"},{"he":"חזן - יְהַלְלוּ אֶת שֵׁם ה' כִּי נִשגָּב שְׁמו לְבַדּו:"},{"he":"קהל - הודו עַל אֶרֶץ וְשָׁמָיִם:"},{"he":"וַיָּרֶם קֶרֶן לְעַמּו תְּהִלָּה לְכָל חֲסִידָיו לִבְנֵי יִשרָאֵל עַם קְרבו הַלְלוּיָהּ:"}]},{"id":"torah-reading-returning-sefer-to-aron-ledavid","heading":"LeDavid","group":"Torah Reading · Returning Sefer to Aron","lines":[{"he":"לְדָוִד מִזְמור. לה' הָאָרֶץ וּמְלואָהּ. תֵּבֵל וְישְׁבֵי בָהּ:"},{"he":"כִּי הוּא עַל יַמִּים יְסָדָהּ. וְעַל נְהָרות יְכונְנֶהָ:"},{"he":"מִי יַעֲלֶה בְהַר ה'. וּמִי יָקוּם בִּמְקום קָדְשׁו:"},{"he":"נְקִי כַפַּיִם וּבַר לֵבָב. אֲשֶׁר לא נָשא לַשָּׁוְא נַפְשִׁי וְלא נִשְׁבַּע לְמִרְמָה:"},{"he":"יִשּא בְרָכָה מֵאֵת ה'. וּצְדָקָה מֵאֱלהֵי יִשְׁעו:"},{"he":"זֶה דּור דּרְשָׁיו. מְבַקְשֵׁי פָנֶיךָ יַעֲקב סֶלָה:"},{"he":"שאוּ שְׁעָרִים רָאשֵׁיכֶם וְהִנָּשאוּ פִּתְחֵי עולָם. וְיָבוא מֶלֶךְ הַכָּבוד:"},{"he":"מִי זֶה מֶלֶךְ הַכָּבוד. ה' עִזּוּז וְגִבּור. ה' גִּבּור מִלְחָמָה:"},{"he":"שאוּ שְׁעָרִים רָאשֵׁיכֶם וּשאוּ פִּתְחֵי עולָם. וְיָבא מֶלֶךְ הַכָּבוד:"},{"he":"מִי הוּא זֶה מֶלֶךְ הַכָּבוד. ה' צְבָאות הוּא מֶלֶךְ הַכָּבוד סֶלָה:"}]},{"id":"torah-reading-returning-sefer-to-aron-uvenucho-yomar","heading":"Uvenucho Yomar","group":"Torah Reading · Returning Sefer to Aron","lines":[{"he":"כשמכניסים הס\"ת להיכל אומרים זה:"},{"he":"וּבְנֻחה יאמַר. שׁוּבָה ה' רִבְבות אַלְפֵי יִשרָאֵל:"},{"he":"קוּמָה ה' לִמְנוּחָתֶךָ. אַתָּה וַאֲרון עֻזֶּךָ:"},{"he":"כּהֲנֶיךָ יִלְבְּשׁוּ צֶדֶק. וַחֲסִידֶיךָ יְרַנֵּנוּ:"},{"he":"בַּעֲבוּר דָּוִד עַבְדֶּךָ אַל תָּשֵׁב פְּנֵי מְשִׁיחֶךָ:"},{"he":"כִּי לֶקַח טוב נָתַתִּי לָכֶם. תּורָתִי אַל תַּעֲזבוּ:"},{"he":"עֵץ חַיִּים הִיא לַמַּחֲזִיקִים בָּהּ. וְתמְכֶיהָ מְאֻשָּׁר:"},{"he":"דְּרָכֶיהָ דַרְכֵי נעַם וְכָל נְתִיבתֶיהָ שָׁלום:"},{"he":"הֲשִׁיבֵנוּ ה' אֵלֶיךָ וְנָשׁוּבָה. חַדֵּשׁ יָמֵינוּ כְּקֶדֶם:"}]},{"id":"amidah-patriarchs","heading":"Patriarchs","group":"Amidah","lines":[{"he":"אֲדנָי שפָתַי תִּפְתָּח וּפִי יַגִּיד תְּהִלָּתֶךָ:"},{"he":"בָּרוּךְ אַתָּה ה' אֱלהֵינוּ וֵאלהֵי אֲבותֵינוּ. אֱלהֵי אַבְרָהָם. אֱלהֵי יִצְחָק. וֵאלהֵי יַעֲקב. הָאֵל הַגָּדול הַגִּבּור וְהַנּורָא אֵל עֶלְיון. גּומֵל חֲסָדִים טובִים. וְקונֵה הַכּל. וְזוכֵר חַסְדֵּי אָבות. וּמֵבִיא גואֵל לִבְנֵי בְנֵיהֶם לְמַעַן שְׁמו בְּאַהֲבָה:"},{"he":"בעשי\"ת זָכְרֵנוּ לְחַיִּים. מֶלֶךְ חָפֵץ בַּחַיִּים. וְכָתְבֵנוּ בְּסֵפֶר הַחַיִּים. לְמַעַנְךָ אֱלהִים חַיִּים:"},{"he":"מֶלֶךְ עוזֵר וּמושִׁיעַ וּמָגֵן:"},{"he":"בָּרוּךְ אַתָּה ה', מָגֵן אַבְרָהָם:"}]},{"id":"amidah-divine-might","heading":"Divine Might","group":"Amidah","lines":[{"he":"אַתָּה גִּבּור לְעולָם אֲדנָי. מְחַיֵּה מֵתִים אַתָּה רַב לְהושִׁיעַ:"},{"he":"בקיץ - מורִיד הַטָּל:"},{"he":"בחורף - מַשִּׁיב הָרוּחַ וּמורִיד הַגָּשֶּׁם:"},{"he":"מְכַלְכֵּל חַיִּים בְּחֶסֶד. מְחַיֶּה מֵתִים בְּרַחֲמִים רַבִּים. סומֵךְ נופְלִים. וְרופֵא חולִים וּמַתִּיר אֲסוּרִים. וּמְקַיֵּם אֱמוּנָתו לִישֵׁנֵי עָפָר. מִי כָמוךָ בַּעַל גְּבוּרות וּמִי דומֶה לָּךְ. מֶלֶךְ מֵמִית וּמְחַיֶּה וּמַצְמִיחַ יְשׁוּעָה:"},{"he":"בעשי\"ת - מִי כָמוךָ אַב הָרַחֲמִים. זוכֵר יְצוּרָיו לְחַיִּים בְּרַחֲמִים:"},{"he":"וְנֶאֱמָן אַתָּה לְהַחֲיות מֵתִים:"},{"he":"בָּרוּךְ אַתָּה ה', מְחַיֵּה הַמֵּתִים:"}]},{"id":"amidah-kedushah","heading":"Kedushah","group":"Amidah","lines":[{"he":"קדושה בחזרת הש\"ץ:"},{"he":"נְקַדֵּשׁ אֶת שִׁמְךָ בָּעולָם. כְּשֵׁם שֶׁמַּקְדִּישִׁים אותו בִּשְׁמֵי מָרום. כַּכָּתוּב עַל יַד נְבִיאֶךָ:"},{"he":"וְקָרָא זֶה אֶל זֶה וְאָמַר:"},{"he":"קו\"ח - קָדושׁ. קָדושׁ. קָדושׁ ה' צְבָאות. מְלא כָל הָאָרֶץ כְּבודו:"},{"he":"חזן - לְעֻמָתָם בָּרוּךְ יאמֵרוּ:"},{"he":"קו\"ח - בָּרוּךְ כְּבוד ה' מִמְּקומו:"},{"he":"חזן - וּבְדִבְרֵי קָדְשְׁךָ כָּתוּב לֵאמר:"},{"he":"קו\"ח - יִמְלךְ ה' לְעולָם. אֱלהַיִךְ צִיּון לְדר וָדר. הַלְלוּיָהּ:"},{"he":"לחזן - לְדור וָדור נַגִּיד גָּדְלֶךָ וּלְנֵצַח נְצָחִים קְדֻשָּׁתְךָ נַקְדִּישׁ. וְשִׁבְחֲךָ אֱלהֵינוּ מִפִּינוּ לא יָמוּשׁ לְעולָם וָעֶד. כִּי אֵל מֶלֶךְ גָּדול וְקָדושׁ אָתָּה:"},{"he":"בָּרוּךְ אַתָּה ה' הָאֵל בעשי\"ת הַמֶּלֶךְ הַקָּדושׁ:"}]},{"id":"amidah-holiness-of-god","heading":"Holiness of God","group":"Amidah","lines":[{"he":"אַתָּה קָדושׁ וְשִׁמְךָ קָדושׁ וּקְדושִׁים בְּכָל יום יְהַלְּלוּךָ סֶּלָה:"},{"he":"בָּרוּךְ אַתָּה ה', הָאֵל בעשי\"ת הַמֶּלֶךְ הַקָּדושׁ:"}]},{"id":"amidah-sanctity-of-the-day","heading":"Sanctity of the Day","group":"Amidah","lines":[{"he":"אַתָּה אֶחָד וְשִׁמְךָ אֶחָד וּמִי כְּעַמְּךָ יִשְׂרָאֵל גּוֹי אֶחָד בָּאָרֶץ."},{"he":"תִּפְאֶרֶת גְּדֻלָּה וַעֲטֶרֶת יְשׁוּעָה יוֹם מְנוּחָה וּקְדֻשָּׁה לְעַמְּךָ נָתָתָּ."},{"he":"אַבְרָהָם יָגֵל יִצְחָק יְרַנֵּן יַעֲקֹב וּבָּנָיו יָנוּחוּ בוֹ."},{"he":"מְנוּחַת אַהֲבָה וּנְדָבָה. מְנוּחַת אֱמֶת וֶאֱמוּנָה. מְנוּחַת שָׁלוֹם וְשַׁלְוָה וְהַשְׁקֵט וָבֶטַח"},{"he":"מְנוּחָה שְׁלֵמָה שָׁאַתָּה רוֹצֶה בָּהּ."},{"he":"יַכִּירוּ בָּנֶיךָ וְיֵדְעוּ כִּי מֵאִתְּךָ הִיא מְנוּחָתָם וְעַל מְנוּחָתָם יַקְדִּישׁוּ אֶת שְׁמֶךָ:"}]},{"id":"amidah-temple-service","heading":"Temple Service","group":"Amidah","lines":[{"he":"אֱלֹהֵינוּ וֵאלֹהֵי אֲבוֹתֵינוּ. רְצֵה בִמְנוּחָתֵנוּ. קַדְּשֵׁנוּ בְּמִצְוֹתֶיךָ. וְתֵן חֶלְקֵנוּ בְּתוֹרָתֶךָ. שַׂבְּעֵנוּ מִטּוּבֶךָ. וְשַׂמְּחֵנוּ בִּישׁוּעָתֶךָ. וְטַהֵר לִבֵּנוּ לְעָבְדְּךָ בֶּאֱמֶת. וְהַנְחִילֵנוּ יְהֹוָה אֱלֹהֵינוּ בְּאַהֲבָה וּבְרָצוֹן שַׁבַּת קָדְשֶׁךָ וְיָנוּחוּ בָם יִשְׂרָאֵל מְקַדְּשֵׁי שְׁמֶךָ: בָּרוּךְ אַתָּה יְהֹוָה מְקַדֵּשׁ הַשַׁבָּת:"},{"he":"רְצֵה יְהֹוָה אֱלֹהֵינוּ בְּעַמְּךָ יִשְׂרָאֵל וּבִתְפִלָּתָם. וְהָשֵׁב אֶת הָעֲבוֹדָה לִדְבִיר בֵּיתֶךָ. וְאִשֵּׁי יִשְׂרָאֵל וּתְפִלָּתָם. בְּאַהֲבָה תְקַבֵּל בְּרָצוֹן. וּתְהִי לְרָצוֹן תָּמִיד עֲבוֹדַת יִשְׂרָאֵל עַמֶּךָ:"},{"he":"בשבת בראש חודש ובשבת חול המועד אומרים יעלה ויבא:","note":true},{"he":"אֱלֹהֵינוּ וֵאלֹהֵי אֲבוֹתֵינוּ. יַעֲלֶה וְיָבוֹא וְיַגִּיעַ. וְיֵרָאֶה וְיֵרָצֶה וְיִשָּׁמַע. וְיִפָּקֵד וְיִזָּכֵר זִכְרוֹנֵנוּ וּפִקְדוֹנֵנוּ וְזִכְרוֹן אֲבוֹתֵינוּ. וְזִכְרוֹן מָשִׁיחַ בֶּן דָּוִד עַבְדֶּךָ. וְזִכְרוֹן יְרוּשָׁלַיִם עִיר קָדְשֶׁךָ. וְזִכְרוֹן כָּל עַמְּךָ בֵּית יִשְׂרָאֵל. לְפָנֶיךָ. לִפְלֵיטָה לְטוֹבָה. לְחֵן וּלְחֶסֶד וּלְרַחֲמִים. לְחַיִּים וּלְשָׁלוֹם בְּיוֹם:"},{"he":"בראש חדש - רֹאשׁ הַחֹדֶשׁ:"},{"he":"בחוהמ\"פ - חַג הַמַּצּוֹת:"},{"he":"בחוהמ\"ס - חַג הַסֻּכּוֹת:"},{"he":"הַזֶּה. זָכְרֵנוּ יְהֹוָה אֱלֹהֵינוּ בּוֹ לְטוֹבָה. וּפָקְדֵנוּ בוֹ לִבְרָכָה. וְהוֹשִׁיעֵנוּ בוֹ לְחַיִּים טוֹבִים. וּבִדְבַר יְשׁוּעָה וְרַחֲמִים חוּס וְחָנֵּנוּ וְרַחֵם עָלֵינוּ וְהוֹשִׁיעֵנוּ. כִּי אֵלֶיךָ עֵינֵינוּ. כִּי אֵל מֶלֶךְ חַנּוּן וְרַחוּם אָתָּה:"},{"he":"וְתֶחֱזֶינָה עֵינֵינוּ בְּשׁוּבְךָ לְצִיּוֹן בְּרַחֲמִים:"},{"he":"בָּרוּךְ אַתָּה יְהֹוָה. הַמַּחֲזִיר שְׁכִינָתוֹ לְצִיּוֹן:"}]},{"id":"amidah-thanksgiving-modim","heading":"Modim","group":"Amidah · Thanksgiving","lines":[{"he":"מוֹדִים אֲנַחְנוּ לָךְ. שָׁאַתָּה הוּא יְהֹוָה אֱלֹהֵינוּ וֵאלֹהֵי אֲבוֹתֵינוּ לְעוֹלָם וָעֶד."},{"he":"צוּר חַיֵּינוּ. מָגֵן יִשְׁעֵנוּ אַתָּה הוּא לְדוֹר וָדוֹר:"},{"he":"נוֹדֶה לְּךָ וּנְסַפֵּר תְּהִלָּתֶךָ"},{"he":"עַל חַיֵּינוּ הַמְּסוּרִים בְּיָדֶךָ. וְעַל נִשְׁמוֹתֵינוּ הַפְּקוּדוֹת לָךְ. וְעַל נִסֶּיךָ שֶׁבְּכָל יוֹם עִמָּנוּ. וְעַל נִפְלְאוֹתֶיךָ וְטוֹבוֹתֶיךָ שֶׁבְּכָל עֵת. עֶרֶב וָבֹקֶר וְצָהֳרָיִם:"},{"he":"הַטּוֹב כִּי לֹא כָלוּ רַחֲמֶיךָ. וְהַמְרַחֵם כִּי לֹא תַמּוּ חֲסָדֶיךָ. מֵעוֹלָם קִוִּינוּ לָךְ:"},{"he":"מודים דרבנן:"},{"he":"מוֹדִים אֲנַחְנוּ לָךְ. שָׁאַתָּה הוּא יְהֹוָה אֱלֹהֵינוּ וֵאלֹהֵי אֲבוֹתֵינוּ. אֱלֹהֵי כָל בָּשָׂר. יוֹצְרֵנוּ יוֹצֵר בְּרֵאשִׁית. בְּרָכוֹת וְהוֹדָאוֹת לְשִׁמְךָ הַגָּדוֹל וְהַקָּדוֹשׁ. עַל שֶׁהֶחֱיִיתָנוּ וְקִיַּמְתָּנוּ. כֵּן תְּחַיֵּנוּ וּתְקַיְּמֵנוּ. וְתֶאֱסוֹף גָּלֻיּוֹתֵינוּ לְחַצְרוֹת קָדְשֶׁךָ. לִשְׁמוֹר חֻקֶּיךָ. וְלַעֲשׂוֹת רְצוֹנֶךָ. וּלְעָבְדְךָ בְּלֵבָב שָׁלֵם. עַל שֶׁאֲנַחְנוּ מוֹדִים לָךְ. בָּרוּךְ אֵל הַהוֹדָאוֹת:"}]},{"id":"amidah-thanksgiving-al-hanisim-for-chanukkah","heading":"Al Hanisim for Chanukkah","group":"Amidah · Thanksgiving","lines":[{"he":"בחנוכה ובפורים דמוקפין אומרים זה:"},{"he":"וְעַל הַנִּסִּים וְעַל הַפֻּרְקָן וְעַל הַגְּבוּרוֹת וְעַל הַתְּשׁוּעוֹת וְעַל הַמִּלְחָמוֹת שֶׁעָשִׂיתָ לַאֲבוֹתֵינוּ בַּיָּמִים הָהֵם בִּזְּמַן הַזֶּה:"},{"he":"לחנוכה:"},{"he":"בִּימֵי מַתִּתְיָהוּ בֶּן יוֹחָנָן כֹּהֵן גָּדוֹל חַשְׁמוֹנַאִי וּבָנָיו. כְּשֶׁעָמְדָה מַלְכוּת יָוָן הָרְשָׁעָה עַל עַמְּךָ יִשְׂרָאֵל לְהַשְׁכִּיחָם תּוֹרָתֶךָ וּלְהַעֲבִירָם מֵחֻקֵּי רְצוֹנֶךָ:"},{"he":"וְאַתָּה בְּרַחֲמֶיךָ הָרַבִּים עָמַדְתָּ לָהֶם בְּעֵת צָרָתָם. רַבְתָּ אֶת רִיבָם. דַנְתָּ אֶת דִּינָם. נָקַמְתָּ אֶת נִקְמָתָם. מָסַרְתָּ גִבּוֹרִים בְּיַד חַלָּשִׁים. וְרַבִּים בְּיַד מְעַטִּים. וּטְמֵאִים בְּיַד טְהוֹרִים. וּרְשָׁעִים בְּיַד צַדִּיקִים. וְזֵדִים בְּיַד עוֹסְקֵי תוֹרָתֶךָ. וּלְךָ עָשִׂיתָ שֵׁם גָּדוֹל וְקָדוֹשׁ בְּעוֹלָמֶךָ. וּלְעַמְּךָ יִשְׂרָאֵל עָשִֹׂיתָ תְּשׁוּעָה גְדוֹלָה וּפֻרְקָן כְּהַיּוֹם הַזֶּה:"},{"he":"וְאַחַר כַּךְ בָּאוּ בָנֶיךָ לִדְבִיר בֵּיתֶךָ. וּפִנּוּ אֶת הֵיכָלֶךָ. וְטִהֲרוּ אֶת מִקְדָּשֶׁךָ. וְהִדְלִיקוּ נֵרוֹת בְּחַצְרוֹת קָדְשֶׁךָ. וְקָבְעוּ שְׁמוֹנַת יְמֵי חֲנֻכָּה אֵלּוּ. לְהוֹדוֹת וּלְהַלֵּל לְשִׁמְךָ הַגָּדוֹל:"}]},{"id":"amidah-thanksgiving-al-hanisim-for-purim","heading":"Al Hanisim for Purim","group":"Amidah · Thanksgiving","lines":[{"he":"לפורים:"},{"he":"בִּימֵי מָרְדְּכַי וְאֶסְתֵּר בְּשׁוּשַׁן הַבִּירָה. כְּשֶׁעָמַד עֲלֵיהֶם הָמָן הָרָשָׁע. בִּקֵּשׁ לְהַשְׁמִיד לַהֲרֹג וּלְאַבֵּד אֶת כָּל הַיְּהוּדִים מִנַּעַר וְעַד זָקֵן טַף וְנָשִׁים בְּיוֹם אֶחָד. בִּשְׁלשָׁה עָשָׂר לְחֹדֶשׁ שְׁנֵים עָשָׂר. הוּא חֹדֶשׁ אֲדָר. וּשְׁלָלָם לָבוֹז:"},{"he":"וְאַתָּה בְּרַחֲמֶיךָ הָרַבִּים. הֵפַרְתָּ אֶת עֲצָתוֹ. וְקִלְקַלְתָּ אֶת מַחֲשַׁבְתּוֹ. וַהֲשֵׁבוֹתָ לּוֹ גְּמוּלוֹ בְרֹאשׁוֹ. וְתָלוּ אוֹתוֹ וְאֶת בָּנָיו עַל הָעֵץ:"},{"he":"וְעַל כֻּלָּם יִתְבָּרַךְ וְיִתְרוֹמַם שִׁמְךָ מַלְכֵּנוּ תָּמִיד לְעוֹלָם וָעֶד:"},{"he":"בש\"ת וּכְתֹב לְחַיִּים טוֹבִים כָּל בְּנֵי בְרִיתֶךָ:","note":true},{"he":"וְכֹל הַחַיִּים יוֹדוּךָ סֶּלָה. וִיהַלְלוּ אֶת שִׁמְךָ בֶּאֱמֶת הָאֵל יְשׁוּעָתֵנוּ וְעֶזְרָתֵנוּ סֶלָה:"},{"he":"בָּרוּךְ אַתָּה יְהֹוָה. הַטּוֹב שִׁמְךָ וּלְךָ נָאֶה לְהוֹדוֹת:"}]},{"id":"amidah-peace","heading":"Peace","group":"Amidah","lines":[{"he":"שִׂים שָׁלוֹם טוֹבָה וּבְרָכָה. חַיִּים חֵן וָחֶסֶד וְרַחֲמִים עָלֵינוּ וְעַל כָּל יִשְׂרָאֵל עַמֶּךָ. בָּרְכֵנוּ אָבִינוּ כֻּלָּנוּ כְּאֶחָד בְּאוֹר פָּנֶיךָ. כִּי בְאוֹר פָּנֶיךָ נָתַתָּ לָּנוּ יְהֹוָה אֱלֹהֵינוּ תּוֹרַת חַיִּים וְאַהֲבַת חֶסֶד. וּצְדָקָה וּבְרָכָה וְרַחֲמִים וְחַיִּים וְשָׁלוֹם. וְטוֹב בְּעֵינֶיךָ לְבָרֵךְ אֶת עַמְּךָ יִשְׂרָאֵל בְּכָל עֵת וּבְכָל שָׁעָה בִּשְׁלוֹמֶךָ:"},{"he":"בש\"ת בְּסֵפֶר חַיִּים. בְּרָכָה וְשָׁלוֹם. וּפַרְנָסָה טוֹבָה. יְשׁוּעוֹת וְנֶחָמוֹת. נִזָּכֵר וְנִכָּתֵב לְפָנֶיךָ. אֲנַחְנוּ וְכָל עַמְּךָ בֵּית יִשְׂרָאֵל. לְחַיִּים טוֹבִים וּלְשָׁלוֹם:","note":true},{"he":"בָּרוּךְ אַתָּה יְהֹוָה. הַמְבָרֵךְ אֶת עַמּוֹ יִשְׂרָאֵל בַּשָּׁלוֹם:"}]},{"id":"amidah-concluding-passage","heading":"Concluding Passage","group":"Amidah","lines":[{"he":"יִהְיוּ לְרָצוֹן אִמְרֵי פִי וְהֶגְיוֹן לִבִּי לְפָנֶיךָ. יְהֹוָה צוּרִי וְגוֹאֲלִי:"},{"he":"אֱלֹהַי. נְצֹר לְשׁוֹנִי מֵרָע וּשְׂפָתַי מִדַּבֵּר מִרְמָה. וְלִמְקַלְלַי נַפְשִׁי תִדֹּם. וְנַפְשִׁי כֶּעָפָר לַכֹּל תִּהְיֶה. פְּתַח לִבִּי בְּתוֹרָתֶךָ. וּבְמִצְוֹתֶיךָ תִּרְדֹּף נַפְשִׁי. וְכָל הַחוֹשְׁבִים עָלַי רָעָה. מְהֵרָה הָפֵר עֲצָתָם וְקַלְקֵל מַחֲשַׁבְתָּם:"},{"he":"עֲשֵׂה לְמַעַן שְׁמֶךָ. עֲשֵׂה לְמַעַן יְמִינֶךָ. עֲשֵׂה לְמַעַן קְדֻשָּׁתֶךָ. עֲשֵׂה לְמַעַן תּוֹרָתֶךָ. לְמַעַן יֵחָלְצוּן יְדִידֶיךָ הוֹשִׁיעָה יְמִינְךָ וַעֲנֵנִי:"},{"he":"יִהְיוּ לְרָצוֹן אִמְרֵי פִי וְהֶגְיוֹן לִבִּי לְפָנֶיךָ. יְהֹוָה צוּרִי וְגוֹאֲלִי:"},{"he":"עֹשֶׂה שָׁלוֹם בש\"ת הַשָּׁלוֹם בִּמְרוֹמָיו. הוּא יַעֲשֶׂה שָׁלוֹם עָלֵינוּ וְעַל כָּל יִשְׂרָאֵל. וְאִמְרוּ אָמֵן:"},{"he":"יְהִי רָצוֹן מִלְּפָנֶיךָ יְהֹוָה אֱלֹהֵינוּ וֵאלֹהֵי אֲבוֹתֵינוּ. שֶׁיִּבָּנֶה בֵּית הַמִּקְדָּשׁ בִּמְהֵרָה בְיָמֵינוּ. וְתֵן חֶלְקֵנוּ בְּתוֹרָתֶךָ:"},{"he":"וְשָׁם נַעֲבָדְךָ בְּיִרְאָה כִּימֵי עוֹלָם וּכְשָׁנִים קַדְמוֹנִיוֹת:"}]},{"id":"tzidkatkhah-tzedek","heading":"Tzidkatkhah Tzedek","lines":[{"he":"בימים שא\"א בו תחנון בחול וכן בד' פרשיות אין אומרים צדקתך:"},{"he":"צִדְקָתְךָ צֶדֶק לְעולָם וְתורָתְךָ אֱמֶת:"},{"he":"וְצִדְקָתְךָ אֱלהִים עַד מָרום אֲשֶׁר עָשיתָ גְדולות אֱלהִים מִי כָמוךָ:"},{"he":"צִדְקָתְךָ כְּהַרְרֵי אֵל מִשְׁפָּטֶיךָ תְּהום רַבָּה אָדָם וּבְהֵמָה תּושִׁיעַ ה':"}]},{"id":"kaddish-shalem","heading":"Kaddish Shalem","lines":[{"he":"יִתְגַּדַּל וְיִתְקַדַּשׁ גרסת הגר\"א: יִתְגַּדֵּל וְיִתְקַדֵּשׁ שְׁמֵהּ רַבָּא. ועונים: אמן בְּעָלְמָא דִי בְרָא כִּרְעוּתֵהּ. וְיַמְלִיךְ מַלְכוּתֵהּ, בְּחַיֵיכוֹן וּבְיוֹמֵיכוֹן וּבְחַיֵי דְּכָל בֵּית יִשְׂרָאֵל, בַּעֲגַלָא וּבִזְמַן קָרִיב וְאִמְרוּ אָמֵן: הקהל עונה: אמן. יְהֵא שְׁמֵהּ רַבָּא מְבָרַךְ לְעָלַם וּלְעָלְמֵי עָלְמַיָא: יְהֵא שְׁמֵהּ רַבָּא מְבָרַךְ לְעָלַם וּלְעָלְמֵי עָלְמַיָא: יִתְבָּרַךְ וְיִשְׁתַּבַּח וְיִתְפָּאַר וְיִתְרוֹמַם וְיִתְנַשֵּׂא וְיִתְהַדָּר וְיִתְעַלֶּה וְיִתְהַלָּל , שְׁמֵהּ דְּקוּדְשָׁא בְּרִיךְ הוּא ועונים: בְּרִיךְ הוּא לְעֵילָא מִן כָּל בעשרת ימי תשובה במקום לְעֵילָא מִן כָּל: לְעֵילָא וּלְעֵילָא מִכָּל בִּרְכָתָא וְשִׁירָתָא, תֻּשְׁבְּחָתָא וְנֶחָמָתָא, דַאֲמִירָן בְּעָלְמָא. וְאִמְרוּ אָמֵן: ועונים: אמן קהל: קַבֵּל בְּרַחֲמִים וּבְרָצון אֶת תְּפִלָּתֵנוּ: תִּתְקַבַּל צְלוֹתְהוֹן וּבָעוּתְהוֹן דְּכָל בֵּית יִשְׂרָאֵל קֳדָם אֲבוּהוֹן דִּי בִשְׁמַיָּא , וְאִמְרוּ אָמֵן. ועונים: אמן קהל: יְהִי שֵׁם יְהוָה מְברָךְ מֵעַתָּה וְעַד עולָם: יְהֵא שְׁלָמָא רַבָּא מִן שְׁמַיָא וְחַיִּים עָלֵינו וְעַל כָּל יִשְׂרָאֵל וְאִמְרוּ אָמֵן: ועונים: אמן קהל: עֶזְרִי מֵעִם יְהוָה עשֵׂה שָׁמַיִם וָאָרֶץ: עוֹשֶׂה שָׁלוֹם בעשרת ימי תשובה: השלום בִּמְרוֹמָיו הוּא יַעֲשֶׂה שָׁלוֹם עָלֵינוּ וְעַל כָּל יִשְׂרָאֵל, וְאִמְרוּ אָמֵן: ועונים: אמן"}]},{"id":"alenu","heading":"Alenu","lines":[{"he":"עָלֵינוּ לְשַׁבֵּחַ לַאֲדון הַכּל. לָתֵת גְּדֻלָּה לְיוצֵר בְּרֵאשִׁית. שֶׁלּא עָשנוּ כְּגויֵי הָאֲרָצות. וְלא שמָנוּ כְּמִשְׁפְּחות הָאֲדָמָה. שֶׁלּא שם חֶלְקֵנוּ כָּהֶם וְגורָלֵנוּ כְּכָל הֲמונָם: שֶׁהֵם מִשְׁתַּחֲוִים לְהֶבֶל וְרִיק וּמִתְפַּלְלִים אֶל אֵל לא יושִׁיעַ: וַאֲנַחְנוּ כּורְעִים וּמִשְׁתַּחֲוִים וּמודִים לִפְנֵי מֶלֶךְ מַלְכֵי הַמְּלָכִים הַקָּדושׁ בָּרוּךְ הוּא: שֶׁהוּא נוטֶה שָׁמַיִם וְיוסֵד אָרֶץ. וּמושַׁב יְקָרו בַּשָּׁמַיִם מִמַּעַל. וּשְׁכִינַת עֻזּו בְּגָבְהֵי מְרומִים: הוּא אֱלהֵינוּ אֵין עוד. אֱמֶת מַלְכֵּנוּ. אֶפֶס זוּלָתו. כַּכָּתוּב בְּתורָתו. וְיָדַעְתָּ הַיּום וַהֲשֵׁבתָ אֶל לְבָבֶךָ. כִּי ה' הוּא הָאֱלהִים בַּשָּׁמַיִם מִמַּעַל וְעַל הָאָרֶץ מִתָּחַת. אֵין עוד:"},{"he":"עַל כֵּן נְקַוֶּה לְּךָ ה' אֱלהֵינוּ לִרְאות מְהֵרָה בְּתִפְאֶרֶת עֻזֶּךָ. לְהַעֲבִיר גִּלּוּלִים מִן הָאָרֶץ. וְהָאֱלִילִים כָּרות יִכָּרֵתוּן. לְתַקֵּן עולָם בְּמַלְכוּת שַׁדַּי. וְכָל בְּנֵי בָשר יִקְרְאוּ בִשְׁמֶךָ לְהַפְנות אֵלֶיךָ כָּל רִשְׁעֵי אָרֶץ. יַכִּירוּ וְיֵדְעוּ כָּל יושְׁבֵי תֵבֵל. כִּי לְךָ תִּכְרַע כָּל בֶּרֶךְ. תִּשָּׁבַע כָּל לָשׁון. לְפָנֶיךָ ה' אֱלהֵינוּ יִכְרְעוּ וְיִפּלוּ. וְלִכְבוד שִׁמְךָ יְקָר יִתֵּנוּ. וִיקַבְּלוּ כֻלָּם אֶת על מַלְכוּתֶךָ. וְתִמְלךְ עֲלֵיהֶם מְהֵרָה לְעולָם וָעֶד. כִּי הַמַּלְכוּת שֶׁלְּךָ הִיא וּלְעולְמֵי עַד תִּמְלךְ בְּכָבוד. כַּכָּתוּב בְּתורָתֶךָ. ה' יִמְלךְ לְעולָם וָעֶד: וְנֶאֱמַר. וְהָיָה ה' לְמֶלֶךְ עַל כָּל הָאָרֶץ. בַּיּום הַהוּא יִהְיֶה ה' אֶחָד וּשְׁמו אֶחָד:"},{"he":"אַל תִּירָא מִפַּחַד פִּתְאם וּמִשּׁאַת רְשָׁעִים כִּי תָבא: עֻצוּ עֵצָה וְתֻפָר. דַּבְּרוּ דָבָר וְלא יָקוּם. כִּי עִמָּנוּ אֵל: וְעַד זִקְנָה אֲנִי הוּא. וְעַד שיבָה אֲנִי אֶסְבּל. אֲנִי עָשיתִי וַאֲנִי אֶשּא וַאֲנִי אֶסְבּל וַאֲמַלֵּט:"}]},{"id":"mourner-s-kaddish","heading":"Mourner's Kaddish","lines":[{"he":"קדיש יתום: אבל: יִתְגַּדַּל וְיִתְקַדַּשׁ שְׁמֵהּ רַבָּא. [קהל: אמן] בְּעָלְמָא דִּי בְרָא כִרְעוּתֵהּ וְיַמְלִיךְ מַלְכוּתֵהּ בְּחַיֵּיכון וּבְיומֵיכון וּבְחַיֵּי דְכָל בֵּית יִשרָאֵל בַּעֲגָלָא וּבִזְמַן קָרִיב, וְאִמְרוּ אָמֵן: [קהל: אמן] קהל ואבל: יְהֵא שְׁמֵהּ רַבָּא מְבָרַךְ לְעָלַם וּלְעָלְמֵי עָלְמַיָּא: אבל: יִתְבָּרַךְ וְיִשְׁתַּבַּח וְיִתְפָּאַר וְיִתְרומַם וְיִתְנַשּא וְיִתְהַדָּר וְיִתְעַלֶּה וְיִתְהַלָּל שְׁמֵהּ דְּקֻדְשָׁא. בְּרִיךְ הוּא. [קהל: בריך הוא:] לְעֵלָּא מִן כָּל בִּרְכָתָא בעשי”ת: לְעֵלָּא לְעֵלָּא מִכָּל וְשִׁירָתָא תֻּשְׁבְּחָתָא וְנֶחֱמָתָא דַּאֲמִירָן בְּעָלְמָא. וְאִמְרוּ אָמֵן: [קהל: אמן] יְהֵא שְׁלָמָא רַבָּא מִן שְׁמַיָּא וְחַיִּים עָלֵינוּ וְעַל כָּל יִשרָאֵל. וְאִמְרוּ אָמֵן: [קהל: אמן] עושה שָׁלום בעשי”ת: הַשָּׁלום בִּמְרומָיו הוּא יַעֲשה שָׁלום עָלֵינוּ וְעַל כָּל יִשרָאֵל וְאִמְרוּ אָמֵן: [קהל: אמן]","note":true}]},{"id":"barchi-nafshi","heading":"Barchi Nafshi","lines":[{"he":"בָּרְכִי נַפְשִׁי אֶת ה'. ה' אֱלהַי גָּדַלְתָּ מְאד. הוד וְהָדָר לָבָשְׁתָּ:"},{"he":"עטֶה אור כַּשּלְמָה. נוטֶה שָׁמַיִם כַּיְרִיעָה:"},{"he":"הַמְקָרֶה בַמַּיִם עֲלִיּותָיו. הַשּם עָבִים רְכוּבו. הַמְהַלֵּךְ עַל כַּנְפֵי רוּחַ:"},{"he":"עשה מַלְאָכָיו רוּחות. מְשָׁרְתָיו אֵשׁ להֵט:"},{"he":"יָסַד אֶרֶץ עַל מְכונֶיהָ. בַּל תִּמּוט עולָם וָעֶד:"},{"he":"תְּהום כַּלְּבוּשׁ כִּסִּיתו. עַל הָרִים יַעַמְדוּ מָיִם:"},{"he":"מִן גַּעֲרָתְךָ יְנוּסוּן. מִן קול רַעַמְךָ יֵחָפֵזוּן:"},{"he":"יַעֲלוּ הָרִים יֵרְדוּ בְקָעות. אֶל מְקום זֶה יָסַדְתָּ לָהֶם:"},{"he":"גְּבוּל שמְתָּ בַּל יַעֲברוּן. בַּל יְשֻׁבוּן לְכַסּות הָאָרֶץ:"},{"he":"הַמְשַׁלֵּחַ מַעְיָנִים. בַּנְּחָלִים בֵּין הָרִים יְהַלֵּכוּן:"},{"he":"יַשְׁקוּ כָּל חַיְתו שדָי. יִשְׁבְּרוּ פְרָאִים צְמָאָם:"},{"he":"עֲלֵיהֶם עוף הַשָּׁמַיִם יִשְׁכּון. מִבֵּין עֳפָאיִם יִתְּנוּ קול:"},{"he":"מַשְׁקֶה הָרִים מֵעֲלִיּותָיו. מִפְּרִי מַעֲשיךָ תִּשבַּע הָאָרֶץ:"},{"he":"מַצְמִיחַ חָצִיר לַבְּהֵמָה. וְעֵשב לַעֲבודַת הָאָדָם. לְהוצִיא לֶחֶם מִן הָאָרֶץ:"},{"he":"וְיַיִן יְשמַּח לְבַב אֱנושׁ. לְהַצְהִיל פָּנִים מִשָּׁמֶן. וְלֶחֶם לְבַב אֱנושׁ יִסְעָד:"},{"he":"יִשבְּעוּ עֲצֵי ה'. אַרְזֵי לְבָנון אֲשֶׁר נָטָע:"},{"he":"אֲשֶׁר שָׁם צִפֳּרִים יְקַנֵּנוּ. חֲסִידָה בְּרושִׁים בֵּיתָהּ:"},{"he":"הָרִים הַגְּבוהִים לַיְּעֵלִים. סְלָעִים מַחְסֶה לַשְּׁפַנִים:"},{"he":"עָשה יָרֵחַ לְמועֲדִים. שֶׁמֶשׁ יָדַע מְבואו:"},{"he":"תָּשֶׁת חשֶׁךְ וִיהִי לָיְלָה. בּו תִרְמש כָּל חַיְתו יָעַר:"},{"he":"הַכְּפִירִים שׁאֲגִים לַטָּרֶף. וּלְבַקֵּשׁ מֵאֵל אָכְלָם:"},{"he":"תִּזְרַח הַשֶּׁמֶשׁ יֵאָסֵפוּן. וְאֶל מְעונתָם יִרְבָּצוּן:"},{"he":"יֵצֵא אָדָם לְפָעֳלו. וְלַעֲבודָתו עֲדֵי עָרֶב:"},{"he":"מָה רַבּוּ מַעֲשיךָ ה'. כֻּלָּם בְּחָכְמָה עָשיתָ. מָלְאָה הָאָרֶץ קִנְיָנֶךָ:"},{"he":"זֶה הַיָּם גָּדול וּרְחַב יָדַיִם. שָׁם רֶמֶש וְאֵין מִסְפָּר. חַיּות קְטַנּות עִם גְּדלות:"},{"he":"שָׁם אֳנִיּות יְהַלֵּכוּן. לִוְיָתָן זֶה יָצַרְתָּ לְשחֶק בּו:"},{"he":"כֻּלָּם אֵלֶיךָ יְשבֵּרוּן. לָתֵת אָכְלָם בְּעִתּו:"},{"he":"תִּתֵּן לָהֶם יִלְקטוּן. תִּפְתַּח יָדְךָ יִשבְּעוּן טוב:"},{"he":"תַּסְתִּיר פָּנֶיךָ יִבָּהֵלוּן. תּסֵף רוּחָם יִגְוָעוּן. וְאֶל עֲפָרָם יְשׁוּבוּן:"},{"he":"תְּשַׁלַּח רוּחֲךָ יִבָּרֵאוּן. וּתְחַדֵּשׁ פְּנֵי אֲדָמָה:"},{"he":"יְהִי כְבוד ה' לְעולָם. יִשמַח ה' בְּמַעֲשיו:"},{"he":"הַמַּבִּיט לָאָרֶץ וַתִּרְעָד. יִגַּע בֶּהָרִים וְיֶעֱשָׁנוּ:"},{"he":"אָשִׁירָה לה' בְּחַיָּי. אֲזַמְּרָה לֵאלהַי בְּעודִי:"},{"he":"יֶעֱרַב עָלָיו שיחִי. אָנכִי אֶשמַח בה':"},{"he":"יִתַּמּוּ חַטָּאִים מִן הָאָרֶץ. וּרְשָׁעִים עוד אֵינָם. בָּרְכִי נַפְשִׁי אֶת ה' הַלְלוּיָהּ:"}]}];

